// Formatos en espanol de Argentina

export const MESES = [
  "enero", "febrero", "marzo", "abril", "mayo", "junio",
  "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre",
] as const;

export const MESES_CORTOS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"] as const;

export function nombreMes(mes: number): string {
  return MESES[mes - 1] ?? "";
}

export function capitalizar(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function entero(v: number): string {
  return Math.round(v).toLocaleString("es-AR");
}

export function decimal(v: number, d = 1): string {
  return v.toLocaleString("es-AR", { minimumFractionDigits: d, maximumFractionDigits: d });
}

export function conSigno(v: number, d = 1): string {
  return (v > 0 ? "+" : v < 0 ? "−" : "") + decimal(Math.abs(v), d);
}

export function valorP(p: number): string {
  return p < 0.001 ? "p < 0,001" : `p = ${decimal(p, 3)}`;
}

// "2009-08" -> "agosto de 2009"
export function mesAnio(anio: number, mes: number): string {
  return `${nombreMes(mes)} de ${anio}`;
}

// "2024-10-01" -> "1 de octubre de 2024"
export function fechaLarga(iso: string): string {
  const [a, m, d] = iso.split("-").map(Number);
  return `${d} de ${nombreMes(m)} de ${a}`;
}

// Numeros con coma decimal, como se escriben en espanol
export function fmt(x: number, decimales: number): string {
  return x.toFixed(decimales).replace(".", ",").replace(/^-/, "−");
}

// Con signo explicito: +0,4 o −0,4
export function fmtSigno(x: number, decimales: number): string {
  const redondeado = Number(x.toFixed(decimales));
  return (redondeado > 0 ? "+" : redondeado < 0 ? "−" : "") + fmt(Math.abs(x), decimales);
}

export function fmtLon(lon: number): string {
  return `${fmt(Math.abs(lon), 1)}° ${lon < 0 ? "O" : "E"}`;
}

export function fmtLat(lat: number): string {
  return `${fmt(Math.abs(lat), 1)}° ${lat < 0 ? "S" : "N"}`;
}
